package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGrades;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * The figures of one person's claims, as the screen works them out: a settled claim's frozen due, else the
 * figure its person's last statement bound it to (not while PENDING), else its live due (amount times the rate in force on its date of
 * the grade its person had on its date, rounded by the sheet's policy; none — n/a — when no rate applies then, or the one that would has ended by then). An
 * overdue claim's due adds, on top of its figure, the late charge: for each full 30 days it is overdue on the sheet's today, the
 * sheet's late percent in force on that boundary date (its due-by plus its grade's grace, plus 30, 60, 90 ... days) of the figure plus
 * the charges of the boundaries before it (compounding), rounded like a due, and
 * the charges added up (a boundary whose percent is 0.00 adds nothing). The floor comes last: an unsettled claim's due is the
 * greater of the sheet's floor in force on its date and its figure plus its late charge. A statement binds the figure only (never
 * the floor or the charge); settling freezes the due in. A correction's live due is its amount times the rate, rounded the same way, with no floor, and it
 * never takes a late charge. The rounding policy: a claim dated before the sheet's policy date (its today when blank)
 * rounds half up, one dated on or after it half to even; a correction goes by the date of the claim it corrects.
 */
public class ClaimFigures {

    private final List<Rate> rates;

    private final PersonGrades grades;

    private final Sheet sheet;

    private final LocalDate today;

    private final LocalDate policyDate;

    private final BigDecimal cap;

    /** @param rates the sheet's rates.
     *  @param grades the person's grades over time.
     *  @param sheet the sheet: its floor on a claim's date (a live due is at least it), and its late percent on each
     *  30-day boundary of a claim's due-by up to its today (the late charge), and its cap in force on its today. */
    public ClaimFigures(List<Rate> rates, PersonGrades grades, Sheet sheet) {
        this.rates = rates;
        this.grades = grades;
        this.sheet = sheet;
        this.today = sheet.getToday();
        this.policyDate = sheet.policyDateInForce();
        this.cap = sheet.getCap();
    }

    /** How the claim's live figures round: half up when the date it rounds by is before the policy date, else half
     *  to even. */
    public RoundingMode rounding(Claim claim) {
        return claim.getRoundsOn().isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The date a claim's lateness counts from: its due-by (fixed when it was created) plus the grace days in force on
     *  its date of the grade its person had on its date (none: its due-by). */
    public LocalDate lateFrom(Claim claim) {
        Integer grace = sheet.gradeGraceOn(grades.on(claim.getDate()), claim.getDate());
        return grace == null ? claim.getDueBy() : claim.getDueBy().plusDays(grace);
    }

    /** Whether a claim is overdue: it is OPEN or PENDING, not deferred, and its due-by plus any grace of its grade
     *  ({@link #lateFrom}) is before the sheet's today. */
    public boolean overdue(Claim claim) {
        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && lateFrom(claim).isBefore(today);
    }

    /** The late charge on a figure: for each full 30 days the claim is overdue, the late percent in force on that
     *  boundary date of it plus the charges before it, rounded like its due, added up; 0.00 when it is not overdue. */
    public BigDecimal lateCharge(Claim claim, BigDecimal figure) {
        if (figure == null || claim.isCorrection() || !overdue(claim)) {
            return BigDecimal.ZERO.setScale(2);
        }
        return chargeByBoundary(claim, figure);
    }

    /** The late percent in force on each full 30-day boundary past the claim's due-by plus any grace
     *  ({@link #lateFrom}), up to the sheet's today, of the figure plus the charges of the boundaries before it, each
     *  rounded like its due, added up. */
    private BigDecimal chargeByBoundary(Claim claim, BigDecimal figure) {
        LocalDate from = lateFrom(claim);
        long periods = ChronoUnit.DAYS.between(from, today) / 30;
        BigDecimal charge = BigDecimal.ZERO.setScale(2);
        for (long k = 1; k <= periods; k++) {
            BigDecimal pct = sheet.latePctOn(from.plusDays(30 * k));
            if (pct.signum() != 0) {
                charge = charge.add(figure.add(charge).multiply(pct).movePointLeft(2).setScale(2, rounding(claim)));
            }
        }
        return charge;
    }

    /** A rate figure: the amount times the percent, divided by 100, rounded as given. */
    public static BigDecimal rateFigure(BigDecimal amount, BigDecimal pct, RoundingMode rounding) {
        return amount.multiply(pct).movePointLeft(2).setScale(2, rounding);
    }

    /** The floor applied last: the greater of the sheet's floor in force on the claim's date and the given due; a
     *  correction takes no floor. */
    private BigDecimal floored(Claim claim, BigDecimal due) {
        if (claim.isCorrection()) {
            return due;
        }
        BigDecimal floor = sheet.floorOn(claim.getDate());
        return floor != null && due.compareTo(floor) < 0 ? floor.setScale(2) : due;
    }

    /** Whether a claim counts toward the totals on a day: only OPEN, PENDING and SETTLED claims do, but not an OPEN
     *  one deferred until after that day. */
    public static boolean counts(Claim claim, LocalDate today) {
        return (claim.getStatus().isOpen() || claim.getStatus() == ClaimStatus.SETTLED) && !claim.isDeferredOn(today);
    }

    /** Whether a claim counts toward the live totals: as {@link #counts}, except its person's OPEN and PENDING
     *  claims dated within a hold of theirs, or all of them once their retirement date is reached, unless a statement
     *  binds them (null person: no holds). */
    public static boolean countsLive(Claim claim, Person person, LocalDate today) {
        return counts(claim, today) && !(person != null && claim.getStatus().isOpen() && !claim.isBound()
                && person.leftOn(claim.getDate(), today));
    }

    /** Whether a claim counts toward a period's live totals: as {@link #countsLive}, taking the status it had at the
     *  end of the period's last day (null: it had not been added by then, so it does not count); a hold takes out
     *  only a claim that is still OPEN or PENDING and unbound now. */
    public static boolean countsAsOf(Claim claim, ClaimStatus then, Person person, LocalDate today) {
        if (then == null || !(then.isOpen() || then == ClaimStatus.SETTLED)) {
            return false;
        }
        boolean deferred = then == ClaimStatus.OPEN && claim.getDeferredUntil() != null && claim.getDeferredUntil().isAfter(today);
        return !deferred && !(person != null && claim.getStatus().isOpen() && !claim.isBound() && person.leftOn(claim.getDate(), today));
    }

    /** The percent of the grade's rate in force on a date; none when that rate's to-date is before it. */
    private Optional<BigDecimal> rateOn(String grade, LocalDate on) {
        return rates.stream()
                .filter(r -> r.getGrade().equals(grade))
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(on))
                .max(Comparator.comparing(Rate::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(r -> !r.endedBy(on))
                .map(Rate::getPct);
    }

    /** The due the claim would have today as an open claim bound by no statement: its live figure at today's rates,
     *  grades and floor, plus the late charge it would carry as an open claim; null when it has none (n/a). */
    public BigDecimal openDue(Claim claim) {
        BigDecimal figure = liveFigure(claim);
        if (figure == null) {
            return null;
        }
        if (claim.isCorrection() || !lateFrom(claim).isBefore(today)) {
            return floored(claim, figure);
        }
        return floored(claim, figure.add(chargeByBoundary(claim, figure)));
    }

    /** The claim's due: its frozen due when settled, else the greater of its floor and its figure plus the late
     *  charge; null when it has none (n/a). */
    public BigDecimal due(Claim claim) {
        if (claim.getDue() != null) {
            return claim.getDue();
        }
        BigDecimal figure = figure(claim);
        return figure == null ? null : floored(claim, figure.add(lateCharge(claim, figure)));
    }

    /** The claim's figure, without any late charge or floor; null when it has none (n/a). */
    public BigDecimal figure(Claim claim) {
        if (claim.getDue() != null) {
            return claim.getDue();
        }
        if (claim.isBound()) {
            return claim.getStatedDue();
        }
        return liveFigure(claim);
    }

    /** The claim's live figure: neither frozen nor bound; null when it has none (n/a). */
    private BigDecimal liveFigure(Claim claim) {
        return rateOn(grades.on(claim.getDate()), claim.getDate())
                .map(pct -> rateFigure(claim.getAmount(), pct, rounding(claim)))
                .orElse(null);
    }

    /** The person's due-total: their counted claims' dues (with any late charge) added up, 0.00 with none; n/a when their grade
     *  in force on the day has no rate in force then, unless a counted claim keeps a figure: a fixed one (settled or bound), or a
     *  live one at another grade they had on its date, or one dated on or before the day (at a rate that has ended since). */
    public String dueTotal(List<Claim> claims, LocalDate today) {
        return dueTotal(claims, today, null);
    }

    /** The person's live due-total, as {@link #dueTotal(List, LocalDate)}; their OPEN claims dated within a hold
     *  of theirs do not count, unless a statement binds them. At most the sheet's cap (n/a is not capped). */
    public String dueTotal(List<Claim> claims, LocalDate today, Person person) {
        String sum = uncappedDueTotal(claims, today, person);
        if (cap == null || "n/a".equals(sum) || new BigDecimal(sum).compareTo(cap) <= 0) {
            return sum;
        }
        return cap.setScale(2).toPlainString();
    }

    /** The person's live due-total before the cap: the sum of their figures. */
    private String uncappedDueTotal(List<Claim> claims, LocalDate today, Person person) {
        List<Claim> counted = claims.stream().filter(c -> countsLive(c, person, today)).toList();
        String grade = grades.on(today);
        boolean kept = counted.stream().anyMatch(c -> c.getDue() != null || (c.isBound() && c.getStatedDue() != null)
                || (!c.isBound() && (!grade.equals(grades.on(c.getDate())) || !c.getDate().isAfter(today)) && figure(c) != null));
        if (rateOn(grade, today).isEmpty() && !kept) {
            return "n/a";
        }
        return counted.stream().map(this::due).filter(f -> f != null)
                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;

/** The claim form's rules, shared by the steps that add claims one at a time and many at once. */
public final class ClaimRules {

    private static final Pattern AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");

    private static final Pattern NUMBER = Pattern.compile("(.+-)?\\d{1,9}");

    private ClaimRules() {
    }

    /** Checks one claim form's fields, with no tags, as ValidateClaim does; a null field is blank. */
    public static ClaimInput check(String amountField, String dateField, String noteField, String correctsField,
            String refField) throws InvalidClaimException {
        return check(amountField, dateField, noteField, correctsField, refField, null);
    }

    /** Checks one claim form's fields as ValidateClaim does; a null field is blank. */
    public static ClaimInput check(String amountField, String dateField, String noteField, String correctsField,
            String refField, String tagsField) throws InvalidClaimException {
        String amount = amountField == null ? "" : amountField.trim();
        String date = dateField == null ? "" : dateField.trim();
        String note = noteField == null ? "" : noteField.trim();
        String corrects = correctsField == null ? "" : correctsField.trim();
        String ref = refField == null ? "" : refField.trim();
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
        }
        if (!corrects.isEmpty() && !NUMBER.matcher(corrects).matches()) {
            throw new InvalidClaimException("Corrects must be a claim number.");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        if (value.signum() < 0 && corrects.isEmpty()) {
            throw new InvalidClaimException("A negative amount is a correction: name the settled claim it corrects.");
        }
        if (value.signum() >= 0 && !corrects.isEmpty()) {
            throw new InvalidClaimException("Only a correction (a negative amount) corrects a claim.");
        }
        LocalDate parsed = null;
        if (!date.isEmpty()) {
            try {
                parsed = LocalDate.parse(date);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("Not a date: " + date);
            }
        }
        return new ClaimInput(value, parsed, note, corrects.isEmpty() ? null : corrects,
                ref.isEmpty() ? null : ref, Tags.normalise(tagsField));
    }

    /** The claim the input makes for the person, not yet saved; refused as BuildClaim refuses it. Its due-by is the
     *  terms-th business day after its date, skipping weekends and the sheet's holidays now on its list. */
    public static Claim make(ClaimInput input, Sheet sheet, Person person, ClaimRepository repository,
            PeriodRepository periods, PersonGradeRepository grades, HolidayRepository holidays) throws InvalidClaimException {
        LocalDate date = input.date() != null ? input.date() : sheet.entryDateInForce();
        int terms = sheet.termsFor(person.getTerms(), grades.gradesOf(person).on(date), date);
        LocalDate dueBy = holidays.dueBy(sheet.getId(), date, terms);
        if (periods.isClosedOn(sheet.getId(), dueBy)) {
            throw new InvalidClaimException("No claim can be added in a closed period.");
        }
        if (person.retiredOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date.");
        }
        LocalDate correctsDate = repository.checkCorrects(sheet.getId(), person.getId(), input.corrects());
        repository.checkRef(sheet.getId(), null, input.ref());
        Claim claim = new Claim(sheet.getId(), person.getId(), input.amount(), date, input.note(), input.corrects());
        claim.setCorrectsDate(correctsDate);
        claim.setRef(input.ref());
        claim.setTags(input.tags());
        claim.setLateEntry(periods.isSoftClosedOn(sheet.getId(), dueBy));
        claim.fixDue(date, terms, holidays.datesOf(sheet.getId()));
        return claim;
    }

    /** Records the claim's adding (its ref, then its tags, at the end, when it has them), and after it, when it is a late entry, its LATE_ENTRY. */
    public static void auditAdded(Claim claim, String personName, String by, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_ADDED", claim, personName, by)
                + (claim.getRef() == null ? "" : " ref=" + claim.getRef())
                + (claim.getTags() == null ? "" : " tags=" + claim.getTags()));
        if (claim.isLateEntry()) {
            audit.record(ClaimAudit.line("LATE_ENTRY", claim, personName, by));
        }
    }

    /** Writes the claim's status log entry as LogClaimStatus does, made by the given user. */
    public static void log(Claim claim, Sheet sheet, ClaimLogRepository log, PersonRepository people,
            RateRepository rates, PersonGradeRepository grades, String by) {
        BigDecimal due = people.findById(claim.getPersonId())
                .map(p -> new ClaimFigures(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(claim.getSheetId()),
                        grades.gradesOf(p), sheet).due(claim))
                .orElse(null);
        log.saveAndFlush(new ClaimLog(claim, by, sheet.getToday(), due));
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Set;
import java.util.TreeSet;
import net.officefloor.hq.app.holiday.BusinessDays;

/** A claim by a person on a sheet: an amount (negative only for a correction, which names the number of the
 * settled claim it corrects), a date, a note (may be empty)
 * a status (DRAFT to start), a number (given when opened), who opened it, a due-by (fixed when created) and a due (fixed when settled). */
@Entity
@Table(name = "claim")
public class Claim {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "person_id", nullable = false)
    private Long personId;

    @Column(nullable = false, precision = 19, scale = 2)
    private BigDecimal amount;

    @Column(name = "claim_date", nullable = false)
    private LocalDate date;

    @Column(nullable = false)
    private String note;

    @Column(nullable = false)
    private String status = ClaimStatus.DRAFT.name();

    /** The number given when the claim was opened (the sheet's next, or the next in its period: P1-1, X-1); null for a
     *  claim never opened; a voided claim keeps it. */
    @Column(name = "claim_number")
    private String number;

    /** The due fixed when the claim was settled; null while it is not settled or its grade had no rate then. */
    @Column(precision = 19, scale = 2)
    private BigDecimal due;

    /** The signed-in name that opened the claim; null while it was never opened. */
    @Column(name = "opened_by")
    private String openedBy;

    /** The signed-in name that last edited the claim (its form or its amount entry); null while it was never edited. */
    @Column(name = "edited_by")
    private String editedBy;

    /** The number of the bulk settle batch that settled it (or left it PENDING); null when settled one at a time. */
    @Column(name = "settle_batch")
    private Integer settleBatch;

    /** Whether the claim is bound by its person's last statement to the figure it had then. */
    @Column(nullable = false)
    private boolean stated;

    /** The figure the claim was bound to by its person's last statement; null while unbound or when it had none (n/a). */
    @Column(name = "stated_due", precision = 19, scale = 2)
    private BigDecimal statedDue;

    /** The claim's due-by: the due-terms-th business day after its due-from, skipping weekends and the sheet's
     *  holidays now on its list; worked out again whenever the holidays change. */
    @Column(name = "due_by", nullable = false)
    private LocalDate dueBy;

    /** The date its due-by counts from, fixed when it was created (its date then). It does not change when its date
     *  changes later. */
    @Column(name = "due_from", nullable = false)
    private LocalDate dueFrom;

    /** The terms its due-by was fixed with when it was created: its person's own, else their grade's in force on its
     *  date, else the sheet's. It does not change when the terms change later. */
    @Column(name = "due_terms", nullable = false)
    private int dueTerms;

    /** The number of the settled claim of the same person this correction corrects; null for any other claim. */
    @Column(name = "corrects")
    private String corrects;

    /** The date of the claim this correction corrects (it rounds by that date); null for any other claim. */
    @Column(name = "corrects_date")
    private LocalDate correctsDate;

    /** Where the claim is listed under its person: newest first by this key. The store gives a new claim the next
     *  key, and a moved claim the next again (it is listed as its new person's newest). */
    @Column(nullable = false, insertable = false, updatable = false)
    private Long listed;

    /** The date the claim is deferred until; null for a claim never deferred. */
    @Column(name = "deferred_until")
    private LocalDate deferredUntil;

    /** The last sheet's today a reminder was written for the claim; null for a claim never reminded. */
    @Column(name = "reminded_on")
    private LocalDate remindedOn;

    /** How many proofs the claim has: raised by one at a time; 0 for a new claim. */
    @Column(nullable = false)
    private int proofs;

    /** The number of the claim this one was split off from; null for a claim not made by a split. */
    @Column(name = "split_from")
    private String splitFrom;

    /** The signed-in name whose open editor locks the claim for everyone else; null while no editor holds it. */
    @Column(name = "locked_by")
    private String lockedBy;

    /** Whether the claim was added while the period its due-by falls in was soft-closed. */
    @Column(name = "late_entry", nullable = false)
    private boolean lateEntry;

    /** The claim's external reference, trimmed; unique on its sheet ignoring case; null for a claim with none. */
    @Column(name = "ref")
    private String ref;

    /** The claim's tags, trimmed, lower-cased, without repeats, sorted and comma separated; null for a claim with none. */
    @Column(name = "tags")
    private String tags;

    /** Every tag the claim has ever carried, sorted and comma separated; null while it never had any. */
    @Column(name = "tags_used")
    private String tagsUsed;

    /** The reason the claim was voided with, from the sheet's list; null when it was voided without one or is not VOID. */
    @Column(name = "void_reason")
    private String voidReason;

    protected Claim() {
    }

    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, String note, String corrects) {
        this.corrects = corrects;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Long getPersonId() {
        return personId;
    }

    public void setPersonId(Long personId) {
        this.personId = personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        this.date = date;
    }

    public LocalDate getDueBy() {
        return dueBy;
    }

    public LocalDate getDueFrom() {
        return dueFrom;
    }

    public int getDueTerms() {
        return dueTerms;
    }

    /** Fixes the date and terms the due-by counts from, and works it out for the sheet's holidays. */
    public void fixDue(LocalDate from, int terms, Set<LocalDate> holidays) {
        this.dueFrom = from;
        this.dueTerms = terms;
        reworkDueBy(holidays);
    }

    /** Works the due-by out again for the sheet's holidays now. */
    public void reworkDueBy(Set<LocalDate> holidays) {
        this.dueBy = BusinessDays.after(dueFrom, dueTerms, holidays);
    }

    public String getNote() {
        return note;
    }

    public void setNote(String note) {
        this.note = note;
    }

    public ClaimStatus getStatus() {
        return ClaimStatus.valueOf(status);
    }

    public void setStatus(ClaimStatus status) {
        this.status = status.name();
    }

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    public BigDecimal getDue() {
        return due;
    }

    public void setDue(BigDecimal due) {
        this.due = due;
    }

    public String getOpenedBy() {
        return openedBy;
    }

    public void setOpenedBy(String openedBy) {
        this.openedBy = openedBy;
    }

    public String getEditedBy() {
        return editedBy;
    }

    public void setEditedBy(String editedBy) {
        this.editedBy = editedBy;
    }

    public Integer getSettleBatch() {
        return settleBatch;
    }

    public void setSettleBatch(Integer settleBatch) {
        this.settleBatch = settleBatch;
    }

    public String getCorrects() {
        return corrects;
    }

    public void setCorrects(String corrects) {
        this.corrects = corrects;
    }

    public LocalDate getCorrectsDate() {
        return correctsDate;
    }

    public void setCorrectsDate(LocalDate correctsDate) {
        this.correctsDate = correctsDate;
    }

    /** The date the claim's rounding goes by: a correction's is the date of the claim it corrects, else its own. */
    public LocalDate getRoundsOn() {
        return correctsDate != null ? correctsDate : date;
    }

    /** Whether the claim is a correction: it names a claim it corrects. */
    public boolean isCorrection() {
        return corrects != null;
    }

    public boolean isStated() {
        return stated;
    }

    public BigDecimal getStatedDue() {
        return statedDue;
    }

    /** Whether the claim shows and totals the figure its person's last statement bound it to: it is bound and not
     *  PENDING (a PENDING claim shows its live figure, and is bound again if rejected). */
    public boolean isBound() {
        return stated && getStatus() != ClaimStatus.PENDING;
    }

    /** Binds the claim to a figure (null: n/a), or unbinds it (live again). */
    public void bind(boolean stated, BigDecimal statedDue) {
        this.stated = stated;
        this.statedDue = stated ? statedDue : null;
    }

    public Long getListed() {
        return listed;
    }

    public LocalDate getDeferredUntil() {
        return deferredUntil;
    }

    public void setDeferredUntil(LocalDate deferredUntil) {
        this.deferredUntil = deferredUntil;
    }

    public LocalDate getRemindedOn() {
        return remindedOn;
    }

    public void setRemindedOn(LocalDate remindedOn) {
        this.remindedOn = remindedOn;
    }

