33	    public static ClaimInput check(String amountField, String dateField, String noteField, String correctsField,
34	            String refField, String tagsField) throws InvalidClaimException {
35	        String amount = amountField == null ? "" : amountField.trim();
36	        String date = dateField == null ? "" : dateField.trim();
37	        String note = noteField == null ? "" : noteField.trim();
38	        String corrects = correctsField == null ? "" : correctsField.trim();
39	        String ref = refField == null ? "" : refField.trim();
40	        if (!AMOUNT.matcher(amount).matches()) {
41	            throw new InvalidClaimException("The amount must be a number with up to two decimals.");
42	        }
43	        if (!corrects.isEmpty() && !NUMBER.matcher(corrects).matches()) {
44	            throw new InvalidClaimException("Corrects must be a claim number.");
45	        }
46	        BigDecimal value = new BigDecimal(amount).setScale(2);
47	        if (value.signum() < 0 && corrects.isEmpty()) {
48	            throw new InvalidClaimException("A negative amount is a correction: name the settled claim it corrects.");
49	        }
50	        if (value.signum() >= 0 && !corrects.isEmpty()) {
51	            throw new InvalidClaimException("Only a correction (a negative amount) corrects a claim.");
52	        }
53	        LocalDate parsed = null;
54	        if (!date.isEmpty()) {
55	            try {
56	                parsed = LocalDate.parse(date);
57	            } catch (DateTimeParseException e) {
58	                throw new InvalidClaimException("Not a date: " + date);
59	            }
60	        }
61	        return new ClaimInput(value, parsed, note, corrects.isEmpty() ? null : corrects,
62	                ref.isEmpty() ? null : ref, Tags.normalise(tagsField));
63	    }
