65	    /** The claim the input makes for the person, not yet saved; refused as BuildClaim refuses it. Its due-by is the
66	     *  terms-th business day after its date, skipping weekends and the sheet's holidays now on its list. */
67	    public static Claim make(ClaimInput input, Sheet sheet, Person person, ClaimRepository repository,
68	            PeriodRepository periods, PersonGradeRepository grades, HolidayRepository holidays) throws InvalidClaimException {
69	        LocalDate date = input.date() != null ? input.date() : sheet.entryDateInForce();
70	        int terms = sheet.termsFor(person.getTerms(), grades.gradesOf(person).on(date), date);
71	        LocalDate dueBy = holidays.dueBy(sheet.getId(), date, terms);
72	        if (periods.isClosedOn(sheet.getId(), dueBy)) {
73	            throw new InvalidClaimException("No claim can be added in a closed period.");
74	        }
75	        if (person.retiredOn(date)) {
76	            throw new InvalidClaimException("No claim can be dated after the person's retirement date.");
