20	import org.springframework.web.bind.annotation.RequestParam;
21	
22	/**
23	 * Moves the claim to the status the action leads to; refuses a change its status does not allow, and an open,
24	 * settle or void by a role the sheet's permission matrix does not allow it to. Opening gives
25	 * the claim the sheet's next number (or, while the sheet's period numbering is on, the next in its period: <period>-<n>,
26	 * X-<n> for a claim in no period) and records who opened it; a voided claim keeps its number (never reused). The one who opened a
27	 * claim cannot settle it, and a clerk (any name not made a steward) settles a claim only when its due is at or below
28	 * the sheet's clerk limit (a due of n/a is within any limit; no limit when the sheet has none): a clerk settling one
29	 * above it leaves it PENDING instead. Only a steward approves a PENDING claim (it is settled, its due fixed at its live
30	 * figure then) or rejects it, with a reason that is not blank (it is OPEN again); the one who opened it cannot approve it. The one who last edited a claim (its form or its amount entry) cannot settle or approve it either. Settling fixes the claim's due at the rate of the grade its
31	 * person had on the claim's date, in force on the claim's date, at least the sheet's floor (or at the figure its person's last statement bound it to), plus its late charge on the sheet's today (none when no rate applies then, so it stays live). A claim deferred until after the sheet's today cannot be settled. A claim whose due is above the proof threshold in force on the claim's date (its person's grade's on that date when one is set, else the sheet's) cannot be settled or approved while it has no proof — refused before the clerk limit is considered. A claim whose due is above the sheet's note threshold in force on the claim's date cannot be opened while its note is empty. A claim whose due-by is in a closed period cannot change status. Only a steward voids a SETTLED claim, and only within 7 days of
32	 * its settlement (its status log's SETTLED date) by the sheet's today; it keeps its number and its frozen due. While the sheet's list of
33	 * void reasons is not empty, a void needs a reason from it, which the claim keeps. Returns the claim's number for the
34	 * audit. A settle that is part of a bulk settle (its batch key) gives the claim that batch's number (the sheet's next
35	 * the first time a claim of the batch settles); one settled on its own has none.
36	 */
37	public class ApplyClaimStatus {
38	
39	    /** How many days after its settlement a steward may still void a SETTLED claim. */
40	    static final int VOID_DAYS = 7;
41	
42	    public String apply(@PathVariable("action") String action, @Val Claim claim, ClaimRepository repository,
43	            EntityManager entityManager, PersonRepository people, RateRepository rates, PersonGradeRepository grades, PeriodRepository periods,
44	            @Val Sheet sheet, RoleRepository roles, ClaimLogRepository log, VoidReasonRepository voidReasons,
45	            @RequestHeader(name = "X-User", required = false) String userHeader,
46	            @RequestParam(name = "reason", required = false) String reason,
47	            @RequestParam(name = "batch", required = false) String batch) throws ClaimStatusException, ClerkLimitException, ProofRequiredException {
48	        return run(action, claim, repository, entityManager, people, rates, grades, periods, sheet, roles, log, voidReasons,
49	                userHeader, reason, batch, false);
50	    }
51	
52	    /** The change itself; on a dry run (a settle only) it refuses what the settle would refuse and changes nothing. */
53	    static String run(String action, Claim claim, ClaimRepository repository,
54	            EntityManager entityManager, PersonRepository people, RateRepository rates, PersonGradeRepository grades, PeriodRepository periods,
55	            Sheet sheet, RoleRepository roles, ClaimLogRepository log, VoidReasonRepository voidReasons,
56	            String userHeader, String reason, String batch, boolean dryRun) throws ClaimStatusException, ClerkLimitException, ProofRequiredException {
57	        if (dryRun && !"settle".equals(action)) {
58	            throw new ClaimStatusException("Only a settle can be checked.");
59	        }
60	        String user = AuditUser.decode(userHeader);
61	        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
62	            throw new ClaimStatusException("A claim in a closed period cannot change status.");
63	        }
64	        String role = roles.roleOf(claim.getSheetId(), user);
65	        if (("open".equals(action) || "settle".equals(action) || "void".equals(action)) && !sheet.allows(action, role)) {
66	            throw new ClerkLimitException("A " + role + " cannot " + action + " a claim.");
67	        }
68	        if ("open".equals(action) && claim.getStatus().after(action) != null) {
69	            // Lock the sheet first (taking a number locks it), then re-read the claim so a concurrent open is seen.
70	            boolean perPeriod = sheet.periodNumberingOn();
71	            if (perPeriod) {
72	                repository.lockSheet(claim.getSheetId());
73	            } else {
74	                repository.takeNextNumber(claim.getSheetId());
75	            }
76	            entityManager.refresh(claim);
77	            ClaimStatus next = check(claim, action);
78	            BigDecimal noteThreshold = sheet.noteThresholdOn(claim.getDate());
79	            if (noteThreshold != null && (claim.getNote() == null || claim.getNote().isBlank())) {
80	                BigDecimal due = people.findById(claim.getPersonId())
81	                        .map(p -> new ClaimFigures(rates.findBySheetIdOrderByGradeAscFromDateAscIdAsc(claim.getSheetId()),
82	                                grades.gradesOf(p), sheet).due(claim))
83	                        .orElse(null);
84	                if (due != null && due.compareTo(noteThreshold) > 0) {
85	                    throw new ClaimStatusException("A claim whose due is above the note threshold needs a note to be opened.");
86	                }
87	            }
88	            if (perPeriod) {
89	                String prefix = periods.findBySheetIdOrderByFromDateAscIdAsc(claim.getSheetId()).stream()
